export const RECIPES = [...BREAKFAST, ...SNACK, ...LUNCH, ...DINNER, ...NHLBI];

/** Храненията, за които е рецептата. */
export const mealsOf = (r) => [].concat(r.meal);

/* ------------------------------ свойства на рецептите ------------------------------ */

/** Хранителни стойности на списък с храни ({food, grams}). */
export function totals(items) {
  const t = { kcal: 0, protein: 0, carbs: 0, fat: 0, fiber: 0, na: 0, k: 0, fe: 0, ca: 0 };
  for (const it of items) {
    const f = FOODS[it.food];
    const k = it.grams / 100;
    t.kcal += f.kcal * k; t.protein += f.p * k; t.carbs += f.c * k; t.fat += f.f * k; t.fiber += f.fib * k; t.na += f.na * k; t.k += f.k * k;
    t.fe += f.fe * k; t.ca += f.ca * k;
  }
  for (const k of Object.keys(t)) t[k] = k === 'fe' ? Math.round(t[k] * 10) / 10 : Math.round(t[k]);
  return t;
}

const STARCH_LOW_GI = new Set(['oats', 'muesli', 'buckwheat', 'quinoa', 'bread', 'ryebread', 'pita', 'rice', 'bulgur', 'pasta', 'lentils', 'beans', 'chickpeas', 'peas', 'sweetpotato']);

/**
 * Етикети, изчислени от съставките: fish, legume, redmeat, vegetarian, vegan,
 * highprotein, fiber, lowk, lowgi, dash, dense (енергийно плътно), quick.
 */
export function recipeTags(r) {
  const items = r.items.map(([food, grams]) => ({ food, grams }));
  const t = totals(items);
  const flags = new Set(items.flatMap(it => [...FOODS[it.food].flags]));
  const tags = new Set();
  if (flags.has('fish') || flags.has('seafood')) tags.add('fish');
  if (items.some(it => FOODS[it.food].flags.has('legume') && it.grams >= 100) || items.some(it => it.food === 'tofu')) tags.add('legume');
  if (flags.has('redmeat')) tags.add('redmeat');
  if (!flags.has('meat') && !flags.has('fish') && !flags.has('seafood')) tags.add('vegetarian');
  if (tags.has('vegetarian') && !flags.has('dairy') && !flags.has('egg') && !flags.has('honey')) tags.add('vegan');
  if (t.kcal && (t.protein * 4) / t.kcal >= 0.28) tags.add('highprotein');
  if (t.kcal && (t.fiber / t.kcal) * 1000 >= 14) tags.add('fiber');
  if (t.kcal && (t.k / t.kcal) * 100 <= 230) tags.add('lowk');
  if (!flags.has('sweet') && !flags.has('highgi')) tags.add('lowgi');
  const salty = items.some(it => FOODS[it.food].flags.has('salt') && FOODS[it.food].cat !== 'grain');
  const veg = items.filter(it => FOODS[it.food].cat === 'veg').reduce((s, it) => s + it.grams, 0);
  if (!salty && !flags.has('redmeat') && (veg >= 150 || mealsOf(r).some(m => m === 'snack' || m === 'breakfast'))) tags.add('dash');
  if (t.kcal && items.some(it => ['nuts', 'fat'].includes(FOODS[it.food].cat) && it.grams >= 15)) tags.add('dense');
  if (r.time <= 20) tags.add('quick');
  return tags;
}

/** Основната белтъчна храна — за разнообразие през деня и седмицата. */
export function mainProtein(r) {
  const order = ['fish', 'seafood', 'redmeat', 'meat', 'legume', 'soy', 'egg', 'dairy'];
  const items = r.items.map(([food, grams]) => ({ food, grams })).filter(it => ['protein', 'legume', 'dairy'].includes(FOODS[it.food].cat));
  const top = items.sort((a, b) => FOODS[b.food].p * b.grams - FOODS[a.food].p * a.grams)[0];
  if (!top) return 'plant';
  const f = FOODS[top.food].flags;
  return order.find(x => f.has(x)) || top.food;
}
